#!/usr/bin/env node
// Concatenates shared front-end scripts into one file per bundle, so a page
// loads the whole "logged-in app shell" with a single <script> tag instead of
// listing the same eleven files (and forgetting one: register.html once had
// no toast.js, listening.html no api-client.js — see docs/STUDENT_UI_AUDIT.md).
//
// Every source is an IIFE that only touches `window` — no top-level 'use
// strict', no document.currentScript — so plain concatenation behaves exactly
// like the separate tags did, in the same order.
//
// Bundles are GENERATED and committed (the static site has no build step).
// Edit the sources, then run scripts/stamp-asset-versions.js, which rebuilds
// them before stamping; frontend/tests/bundles.test.js fails on a stale one.
//
//   node scripts/build-bundles.js          rewrite bundles in place
//   node scripts/build-bundles.js --check  exit 1 if a bundle is stale
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..', 'frontend');

const BUNDLES = {
  // Everything a logged-in student page needs before its own scripts run:
  // auth guard, upgrade/popup plumbing, the nav, toasts, the peer chat
  // widget and the shared fetch-response handler. Order matters only for
  // auth.js, which needs window.AuthService at load time.
  'js/bundles/app-shell.js': [
    'js/shared/auth-service.js',
    'js/auth.js',
    'js/upgrade-modal.js',
    'js/shared/popup-queue.js',
    'js/nav.js',
    'js/shared/playful.js',
    'js/shared/sound-effects.js',
    'js/shared/utils.js',
    'js/shared/toast.js',
    'js/shared/peer-chat-widget.js',
    'js/shared/api-client.js',
  ],
};

const lf = (s) => s.replace(/\r\n/g, '\n');

function render(sources) {
  const head =
    '// GENERATED by scripts/build-bundles.js — do not edit by hand.\n' +
    '// Edit the source files listed below, then run:\n' +
    '//   node scripts/stamp-asset-versions.js\n' +
    sources.map((s) => '//   - ' + s).join('\n') + '\n';
  return head + sources
    .map((s) => '\n// ── ' + s + ' ' + '─'.repeat(Math.max(4, 70 - s.length)) + '\n' +
      lf(fs.readFileSync(path.join(ROOT, s), 'utf8')).trimEnd() + '\n;\n')
    .join('');
}

// Returns the list of bundles whose file on disk differs from a fresh build.
function build({ write }) {
  const stale = [];
  for (const [out, sources] of Object.entries(BUNDLES)) {
    const abs = path.join(ROOT, out);
    const want = render(sources);
    const have = fs.existsSync(abs) ? lf(fs.readFileSync(abs, 'utf8')) : null;
    if (have === want) continue;
    stale.push(out);
    if (write) {
      fs.mkdirSync(path.dirname(abs), { recursive: true });
      fs.writeFileSync(abs, want, 'utf8');
    }
  }
  return stale;
}

module.exports = { build, BUNDLES };

if (require.main === module) {
  const check = process.argv.includes('--check');
  const stale = build({ write: !check });
  if (check && stale.length) {
    console.error('Stale bundle(s): ' + stale.join(', ') + '\nRun: node scripts/stamp-asset-versions.js');
    process.exit(1);
  }
  console.log(stale.length ? (check ? '' : 'Rebuilt ' + stale.join(', ')) : 'All bundles up to date.');
}
